<?php
function save_form(string $type): void { $name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$message=trim((string)($_POST['message']??''));if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$message===''){http_response_code(422);exit('Please complete all fields.');}$dir=__DIR__.'/data';if(!is_dir($dir))mkdir($dir,0775,true);$file=$dir.'/'.$type.'.json';$items=is_file($file)?(json_decode((string)file_get_contents($file),true)?:[]):[];$items[]=['submitted_at'=>date('c'),'name'=>$name,'email'=>$email,'message'=>$message,'rating'=>$_POST['rating']??null];file_put_contents($file,json_encode($items,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),LOCK_EX);header('Location: '.$type.'.html?success=1');exit;}
